DO $$ DECLARE j record; old_gate text:='WHERE is_active = true AND next_run_at <= now()'; new_gate text:=$g$WHERE is_active = true AND next_run_at <= now() AND (key <> 'process_inapp_delivery' OR EXISTS (SELECT 1 FROM public.inapp_delivery_jobs WHERE (status IN ('pending','retry') AND next_attempt_at <= now()) OR (status = 'running' AND lease_until < now())))$g$; BEGIN FOR j IN SELECT jobid,command FROM cron.job WHERE jobname='automation-brain-tick' LOOP IF position(old_gate in j.command)=0 THEN RAISE EXCEPTION 'Automation gate changed; review required'; END IF; PERFORM cron.alter_job(job_id:=j.jobid,command:=replace(j.command,old_gate,new_gate)); END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.validate_inapp_audience_filter(p_filter jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF p_filter IS NULL OR jsonb_typeof(p_filter)<>'object' OR COALESCE(p_filter->>'audience_kind','members') NOT IN ('members','members_and_staff','staff') OR COALESCE(p_filter->>'member_status',p_filter->>'status','all') NOT IN ('all','active','expired','recent_expired','inactive_30','inactive_60','frozen','pending_dues') THEN RAISE EXCEPTION 'Invalid In-App audience' USING ERRCODE='22023'; END IF;
 IF p_filter ? 'staff_roles' THEN IF jsonb_typeof(p_filter->'staff_roles')<>'array' THEN RAISE EXCEPTION 'Invalid staff roles' USING ERRCODE='22023'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_filter->'staff_roles') r(role) WHERE role NOT IN ('owner','admin','manager','staff','trainer')) THEN RAISE EXCEPTION 'Invalid staff role' USING ERRCODE='22023'; END IF; END IF;
END $$;
REVOKE ALL ON FUNCTION public.validate_inapp_audience_filter(jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.validate_inapp_audience_filter(jsonb) TO service_role;
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.inapp_campaign_user_ids(uuid,jsonb)'::regprocedure); d:=replace(d,'RETURN QUERY SELECT DISTINCT','PERFORM public.validate_inapp_audience_filter(p_filter); RETURN QUERY SELECT DISTINCT'); EXECUTE d; END $$;